"""Agrega el módulo de reportes (4 reportes consolidados, página y pruebas).

Uso, desde la raíz del repositorio y con una rama nueva (feature/reportes):
    python3 aplicar_reportes.py

Antes de modificar nada comprueba que todos los textos esperados existan;
si falta alguno, se detiene sin tocar ningún archivo.
"""
from pathlib import Path

NUEVOS = {'app/servicios/reportes.py': '"""Consultas de los reportes consolidados (solo lectura).\n\nLas cantidades se agrupan por unidad (KG o UND) para no sumar kilos con unidades.\n"""\n\nfrom contextlib import closing\nfrom pathlib import Path\nimport sqlite3\n\n\ndef _consultar(ruta: Path, sql: str, parametros: dict | None = None) -> list[dict]:\n    with closing(sqlite3.connect(ruta)) as conexion:\n        conexion.execute("PRAGMA query_only = ON")\n        conexion.row_factory = sqlite3.Row\n        filas = conexion.execute(sql, parametros or {}).fetchall()\n    return [dict(fila) for fila in filas]\n\n\ndef inventario_por_categoria(ruta: Path) -> list[dict]:\n    return _consultar(\n        ruta,\n        """\n        SELECT c.nombre AS categoria,\n               COUNT(p.id_producto) AS productos,\n               COALESCE(SUM(CASE WHEN p.stock_actual <= p.stock_minimo THEN 1 END), 0)\n                   AS bajo_minimo,\n               COALESCE(SUM(p.stock_actual * p.precio_venta), 0) AS valor_inventario\n        FROM categorias AS c\n        LEFT JOIN productos AS p\n               ON p.id_categoria = c.id_categoria AND p.activo = 1\n        GROUP BY c.id_categoria\n        ORDER BY valor_inventario DESC, c.nombre\n        """,\n    )\n\n\ndef stock_bajo(ruta: Path) -> list[dict]:\n    return _consultar(\n        ruta,\n        """\n        SELECT p.id_producto,\n               p.nombre,\n               c.nombre AS categoria,\n               pr.nombre AS proveedor,\n               pr.telefono AS proveedor_telefono,\n               p.unidad,\n               p.stock_actual,\n               p.stock_minimo,\n               p.stock_minimo - p.stock_actual AS faltante\n        FROM productos AS p\n        JOIN categorias AS c ON c.id_categoria = p.id_categoria\n        JOIN proveedores AS pr ON pr.id_proveedor = p.id_proveedor\n        WHERE p.activo = 1 AND p.stock_actual <= p.stock_minimo\n        ORDER BY faltante DESC, p.nombre\n        """,\n    )\n\n\ndef movimientos_por_proveedor(\n    ruta: Path, desde: str | None, hasta: str | None\n) -> list[dict]:\n    return _consultar(\n        ruta,\n        """\n        SELECT pr.nombre AS proveedor,\n               p.unidad,\n               COUNT(m.id_movimiento) AS movimientos,\n               COALESCE(SUM(CASE WHEN m.tipo = \'ENTRADA\' THEN m.cantidad END), 0)\n                   AS entradas,\n               COALESCE(SUM(CASE WHEN m.tipo = \'SALIDA\' THEN m.cantidad END), 0)\n                   AS salidas\n        FROM movimientos AS m\n        JOIN productos AS p ON p.id_producto = m.id_producto\n        JOIN proveedores AS pr ON pr.id_proveedor = p.id_proveedor\n        WHERE (:desde IS NULL OR date(m.fecha) >= :desde)\n          AND (:hasta IS NULL OR date(m.fecha) <= :hasta)\n        GROUP BY pr.id_proveedor, p.unidad\n        ORDER BY pr.nombre, p.unidad\n        """,\n        {"desde": desde, "hasta": hasta},\n    )\n\n\ndef movimientos_por_usuario(\n    ruta: Path, desde: str | None, hasta: str | None\n) -> list[dict]:\n    return _consultar(\n        ruta,\n        """\n        SELECT u.nombre AS usuario,\n               r.nombre AS rol,\n               p.unidad,\n               COUNT(m.id_movimiento) AS movimientos,\n               COALESCE(SUM(CASE WHEN m.tipo = \'ENTRADA\' THEN m.cantidad END), 0)\n                   AS entradas,\n               COALESCE(SUM(CASE WHEN m.tipo = \'SALIDA\' THEN m.cantidad END), 0)\n                   AS salidas\n        FROM movimientos AS m\n        JOIN usuarios AS u ON u.id_usuario = m.id_usuario\n        JOIN roles AS r ON r.id_rol = u.id_rol\n        JOIN productos AS p ON p.id_producto = m.id_producto\n        WHERE (:desde IS NULL OR date(m.fecha) >= :desde)\n          AND (:hasta IS NULL OR date(m.fecha) <= :hasta)\n        GROUP BY u.id_usuario, p.unidad\n        ORDER BY u.nombre, p.unidad\n        """,\n        {"desde": desde, "hasta": hasta},\n    )\n', 'app/schemas_reportes.py': 'from pydantic import BaseModel\n\n\nclass InventarioCategoria(BaseModel):\n    categoria: str\n    productos: int\n    bajo_minimo: int\n    valor_inventario: float\n\n\nclass StockBajo(BaseModel):\n    id_producto: int\n    nombre: str\n    categoria: str\n    proveedor: str\n    proveedor_telefono: str | None\n    unidad: str\n    stock_actual: float\n    stock_minimo: float\n    faltante: float\n\n\nclass MovimientosProveedor(BaseModel):\n    proveedor: str\n    unidad: str\n    movimientos: int\n    entradas: float\n    salidas: float\n\n\nclass MovimientosUsuario(BaseModel):\n    usuario: str\n    rol: str\n    unidad: str\n    movimientos: int\n    entradas: float\n    salidas: float\n', 'app/api/reportes.py': 'from datetime import date\n\nfrom fastapi import APIRouter, HTTPException, Request\n\nfrom app.schemas_reportes import (\n    InventarioCategoria,\n    MovimientosProveedor,\n    MovimientosUsuario,\n    StockBajo,\n)\nfrom app.servicios.reportes import (\n    inventario_por_categoria,\n    movimientos_por_proveedor,\n    movimientos_por_usuario,\n    stock_bajo,\n)\n\nrouter = APIRouter(prefix="/reportes", tags=["Reportes"])\n\n\ndef _periodo(desde: date | None, hasta: date | None) -> tuple[str | None, str | None]:\n    if desde and hasta and desde > hasta:\n        raise HTTPException(\n            status_code=422,\n            detail="La fecha inicial no puede ser posterior a la final",\n        )\n    return (\n        desde.isoformat() if desde else None,\n        hasta.isoformat() if hasta else None,\n    )\n\n\n@router.get("/inventario-por-categoria", response_model=list[InventarioCategoria])\ndef reporte_inventario_por_categoria(request: Request) -> list[dict]:\n    return inventario_por_categoria(request.app.state.database_path)\n\n\n@router.get("/stock-bajo", response_model=list[StockBajo])\ndef reporte_stock_bajo(request: Request) -> list[dict]:\n    return stock_bajo(request.app.state.database_path)\n\n\n@router.get("/movimientos-por-proveedor", response_model=list[MovimientosProveedor])\ndef reporte_movimientos_por_proveedor(\n    request: Request,\n    desde: date | None = None,\n    hasta: date | None = None,\n) -> list[dict]:\n    inicio, fin = _periodo(desde, hasta)\n    return movimientos_por_proveedor(request.app.state.database_path, inicio, fin)\n\n\n@router.get("/movimientos-por-usuario", response_model=list[MovimientosUsuario])\ndef reporte_movimientos_por_usuario(\n    request: Request,\n    desde: date | None = None,\n    hasta: date | None = None,\n) -> list[dict]:\n    inicio, fin = _periodo(desde, hasta)\n    return movimientos_por_usuario(request.app.state.database_path, inicio, fin)\n', 'app/static/reportes/index.html': '<!doctype html>\n<html lang="es">\n  <head>\n    <meta charset="utf-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1">\n    <title>Reportes | Salsamentaria</title>\n    <link\n      href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css"\n      rel="stylesheet"\n      integrity="sha384-QWTKZyjpPEjISv5WaRU9OFeRpok6YctnYmDr5pNlyT2bRjXh0JMhjY6hW+ALEwIH"\n      crossorigin="anonymous">\n    <link rel="stylesheet" href="/static/styles.css?v=14">\n  </head>\n  <body>\n    <main class="container py-4 py-lg-5">\n      <header class="page-heading mb-4">\n        <div>\n          <p class="eyebrow mb-2">Análisis</p>\n          <h1 class="display-6 fw-bold mb-2">Reportes</h1>\n          <p class="text-secondary mb-0">Consultas consolidadas del inventario y de los movimientos.</p>\n        </div>\n      </header>\n\n      <div id="mensaje" class="alert d-none" role="alert"></div>\n\n      <section class="card app-card">\n        <div class="card-body border-bottom">\n          <div class="row g-2 align-items-end">\n            <div class="col-lg-4">\n              <label for="reporte" class="form-label mb-1">Reporte</label>\n              <select id="reporte" class="form-select">\n                <option value="inventario-por-categoria">Inventario por categoría</option>\n                <option value="stock-bajo">Productos con stock bajo</option>\n                <option value="movimientos-por-proveedor">Movimientos por proveedor</option>\n                <option value="movimientos-por-usuario">Movimientos por usuario</option>\n              </select>\n            </div>\n            <div class="col-6 col-lg-2 filtro-fechas">\n              <label for="desde" class="form-label mb-1">Desde</label>\n              <input id="desde" type="date" class="form-control">\n            </div>\n            <div class="col-6 col-lg-2 filtro-fechas">\n              <label for="hasta" class="form-label mb-1">Hasta</label>\n              <input id="hasta" type="date" class="form-control">\n            </div>\n            <div class="col-12 col-lg d-flex gap-2">\n              <button id="consultar" type="button" class="btn btn-primary">Consultar</button>\n              <button id="descargar-csv" type="button" class="btn btn-outline-secondary" disabled>\n                Descargar CSV\n              </button>\n            </div>\n          </div>\n          <p id="descripcion-reporte" class="text-secondary small mb-0 mt-3"></p>\n        </div>\n        <div class="card-body p-0">\n          <div class="table-responsive">\n            <table class="table table-hover align-middle mb-0">\n              <thead class="table-light">\n                <tr id="cabecera-reporte"></tr>\n              </thead>\n              <tbody id="cuerpo-reporte">\n                <tr><td class="text-center text-secondary py-4">Cargando reporte...</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n        <div class="card-footer bg-transparent">\n          <span class="result-count" id="total-filas"></span>\n        </div>\n      </section>\n    </main>\n\n    <script src="/static/layout.js?v=1"></script>\n    <script src="/static/auth.js?v=3"></script>\n    <script src="/static/reportes/reportes.js?v=1"></script>\n  </body>\n</html>\n', 'app/static/reportes/reportes.js': 'const REPORTES = {\n  "inventario-por-categoria": {\n    descripcion:\n      "Productos activos por categoría, cuántos están en o bajo el stock mínimo y el valor del inventario (stock × precio de venta).",\n    usaFechas: false,\n    columnas: [\n      { clave: "categoria", titulo: "Categoría" },\n      { clave: "productos", titulo: "Productos activos", tipo: "numero" },\n      { clave: "bajo_minimo", titulo: "En o bajo el mínimo", tipo: "numero" },\n      { clave: "valor_inventario", titulo: "Valor del inventario", tipo: "moneda" },\n    ],\n  },\n  "stock-bajo": {\n    descripcion:\n      "Productos activos con stock igual o inferior al mínimo, los más urgentes primero, con el proveedor al que se les puede pedir.",\n    usaFechas: false,\n    columnas: [\n      { clave: "nombre", titulo: "Producto" },\n      { clave: "categoria", titulo: "Categoría" },\n      { clave: "proveedor", titulo: "Proveedor" },\n      { clave: "proveedor_telefono", titulo: "Teléfono" },\n      { clave: "unidad", titulo: "Unidad" },\n      { clave: "stock_actual", titulo: "Stock actual", tipo: "numero" },\n      { clave: "stock_minimo", titulo: "Stock mínimo", tipo: "numero" },\n      { clave: "faltante", titulo: "Faltante", tipo: "numero" },\n    ],\n  },\n  "movimientos-por-proveedor": {\n    descripcion:\n      "Entradas y salidas de los productos de cada proveedor, separadas por unidad (KG o UND). Sin fechas se incluyen todos los movimientos.",\n    usaFechas: true,\n    columnas: [\n      { clave: "proveedor", titulo: "Proveedor" },\n      { clave: "unidad", titulo: "Unidad" },\n      { clave: "movimientos", titulo: "Movimientos", tipo: "numero" },\n      { clave: "entradas", titulo: "Entradas", tipo: "numero" },\n      { clave: "salidas", titulo: "Salidas", tipo: "numero" },\n    ],\n  },\n  "movimientos-por-usuario": {\n    descripcion:\n      "Cuántos movimientos registró cada usuario, con sus entradas y salidas por unidad. Sin fechas se incluyen todos los movimientos.",\n    usaFechas: true,\n    columnas: [\n      { clave: "usuario", titulo: "Usuario" },\n      { clave: "rol", titulo: "Rol" },\n      { clave: "unidad", titulo: "Unidad" },\n      { clave: "movimientos", titulo: "Movimientos", tipo: "numero" },\n      { clave: "entradas", titulo: "Entradas", tipo: "numero" },\n      { clave: "salidas", titulo: "Salidas", tipo: "numero" },\n    ],\n  },\n};\n\nconst selectorReporte = document.querySelector("#reporte");\nconst campoDesde = document.querySelector("#desde");\nconst campoHasta = document.querySelector("#hasta");\nconst botonConsultar = document.querySelector("#consultar");\nconst botonCsv = document.querySelector("#descargar-csv");\nconst descripcion = document.querySelector("#descripcion-reporte");\nconst cabecera = document.querySelector("#cabecera-reporte");\nconst cuerpo = document.querySelector("#cuerpo-reporte");\nconst totalFilas = document.querySelector("#total-filas");\nconst mensaje = document.querySelector("#mensaje");\n\nconst formatoMoneda = new Intl.NumberFormat("es-CO", {\n  style: "currency",\n  currency: "COP",\n  maximumFractionDigits: 0,\n});\nconst formatoNumero = new Intl.NumberFormat("es-CO", { maximumFractionDigits: 2 });\n\nlet reporteMostrado = null;\nlet filasMostradas = [];\nlet numeroPeticion = 0;\n\nfunction mostrarMensaje(texto, tipo = "danger") {\n  mensaje.textContent = texto;\n  mensaje.className = `alert alert-${tipo}`;\n}\n\nfunction ocultarMensaje() {\n  mensaje.className = "alert d-none";\n}\n\nfunction formatear(valor, tipo) {\n  if (valor === null || valor === undefined || valor === "") return "—";\n  if (tipo === "moneda") return formatoMoneda.format(valor);\n  if (tipo === "numero") return formatoNumero.format(valor);\n  return String(valor);\n}\n\nfunction crearCelda(texto, tipo) {\n  const celda = document.createElement("td");\n  celda.textContent = texto;\n  if (tipo) celda.className = "text-end";\n  return celda;\n}\n\nfunction dibujarCabecera(columnas) {\n  cabecera.replaceChildren(\n    ...columnas.map((columna) => {\n      const celda = document.createElement("th");\n      celda.textContent = columna.titulo;\n      celda.className = columna.tipo ? "text-end" : "";\n      return celda;\n    }),\n  );\n}\n\nfunction dibujarFilas(columnas, filas) {\n  if (filas.length === 0) {\n    const fila = document.createElement("tr");\n    const celda = document.createElement("td");\n    celda.colSpan = columnas.length;\n    celda.className = "text-center text-secondary py-4";\n    celda.textContent = "No hay datos para los filtros elegidos.";\n    fila.append(celda);\n    cuerpo.replaceChildren(fila);\n    return;\n  }\n  cuerpo.replaceChildren(\n    ...filas.map((dato) => {\n      const fila = document.createElement("tr");\n      fila.append(\n        ...columnas.map((columna) =>\n          crearCelda(formatear(dato[columna.clave], columna.tipo), columna.tipo),\n        ),\n      );\n      return fila;\n    }),\n  );\n}\n\nfunction actualizarFiltros() {\n  const { descripcion: texto, usaFechas } = REPORTES[selectorReporte.value];\n  descripcion.textContent = texto;\n  document\n    .querySelectorAll(".filtro-fechas")\n    .forEach((campo) => campo.classList.toggle("d-none", !usaFechas));\n}\n\nfunction construirUrl(clave) {\n  const parametros = new URLSearchParams();\n  if (REPORTES[clave].usaFechas) {\n    if (campoDesde.value) parametros.set("desde", campoDesde.value);\n    if (campoHasta.value) parametros.set("hasta", campoHasta.value);\n  }\n  const texto = parametros.toString();\n  return `/reportes/${clave}${texto ? `?${texto}` : ""}`;\n}\n\nasync function consultar() {\n  const clave = selectorReporte.value;\n  const reporte = REPORTES[clave];\n  ocultarMensaje();\n\n  if (reporte.usaFechas && campoDesde.value && campoHasta.value && campoDesde.value > campoHasta.value) {\n    mostrarMensaje("La fecha inicial no puede ser posterior a la final.", "warning");\n    return;\n  }\n\n  const peticion = ++numeroPeticion;\n  botonConsultar.disabled = true;\n  botonCsv.disabled = true;\n  try {\n    const respuesta = await fetch(construirUrl(clave));\n    const datos = await respuesta.json().catch(() => null);\n    if (peticion !== numeroPeticion) return;\n    if (!respuesta.ok) {\n      const detalle = typeof datos?.detail === "string" ? datos.detail : null;\n      throw new Error(detalle || `No se pudo generar el reporte (código ${respuesta.status}).`);\n    }\n    reporteMostrado = clave;\n    filasMostradas = datos;\n    dibujarCabecera(reporte.columnas);\n    dibujarFilas(reporte.columnas, datos);\n    totalFilas.textContent = `${datos.length} ${datos.length === 1 ? "fila" : "filas"}`;\n    botonCsv.disabled = datos.length === 0;\n  } catch (error) {\n    if (peticion !== numeroPeticion) return;\n    mostrarMensaje(error.message);\n  } finally {\n    if (peticion === numeroPeticion) botonConsultar.disabled = false;\n  }\n}\n\nfunction celdaCsv(valor) {\n  let texto = valor === null || valor === undefined ? "" : String(valor);\n  // Evita que Excel interprete como fórmula un texto que empieza con = + - @\n  if (typeof valor === "string" && /^[=+\\-@\\t\\r]/.test(texto)) texto = `\'${texto}`;\n  return /[";\\r\\n]/.test(texto) ? `"${texto.replaceAll(\'"\', \'""\')}"` : texto;\n}\n\nfunction descargarCsv() {\n  if (!reporteMostrado) return;\n  const columnas = REPORTES[reporteMostrado].columnas;\n  const lineas = [\n    columnas.map((columna) => celdaCsv(columna.titulo)),\n    ...filasMostradas.map((dato) => columnas.map((columna) => celdaCsv(dato[columna.clave]))),\n  ];\n  // Punto y coma y BOM UTF-8: Excel en español abre bien las columnas y las tildes.\n  const contenido = `\\ufeff${lineas.map((linea) => linea.join(";")).join("\\r\\n")}`;\n  const archivo = new Blob([contenido], { type: "text/csv;charset=utf-8" });\n  const enlace = document.createElement("a");\n  enlace.href = URL.createObjectURL(archivo);\n  enlace.download = `reporte-${reporteMostrado}.csv`;\n  document.body.append(enlace);\n  enlace.click();\n  enlace.remove();\n  URL.revokeObjectURL(enlace.href);\n}\n\nselectorReporte.addEventListener("change", () => {\n  actualizarFiltros();\n  consultar();\n});\nbotonConsultar.addEventListener("click", consultar);\nbotonCsv.addEventListener("click", descargarCsv);\n\nactualizarFiltros();\nconsultar();\n', 'tests/test_reportes.py': 'from contextlib import closing\nimport sqlite3\n\nimport pytest\nfrom fastapi.testclient import TestClient\n\nfrom app.database import inicializar_base_datos\nfrom app.main import crear_app\n\nRUTAS_REPORTES = [\n    "/reportes/inventario-por-categoria",\n    "/reportes/stock-bajo",\n    "/reportes/movimientos-por-proveedor",\n    "/reportes/movimientos-por-usuario",\n]\n\n\ndef preparar_base(ruta):\n    """Datos pequeños con totales fáciles de comprobar a mano."""\n    inicializar_base_datos(ruta)\n    with closing(sqlite3.connect(ruta)) as conexion, conexion:\n        conexion.execute("PRAGMA foreign_keys = ON")\n        conexion.executemany(\n            "INSERT INTO roles (id_rol, nombre) VALUES (?, ?)",\n            [(1, "ADMINISTRADOR"), (2, "VENDEDOR")],\n        )\n        conexion.executemany(\n            "INSERT INTO usuarios (id_usuario, nombre, email, password_hash, id_rol, activo)"\n            " VALUES (?, ?, ?, ?, ?, ?)",\n            [(1, "Ana", "ana@example.com", "x", 1, 1), (2, "Beto", "beto@example.com", "x", 2, 1)],\n        )\n        conexion.executemany(\n            "INSERT INTO categorias (id_categoria, nombre) VALUES (?, ?)",\n            [(1, "Lácteos"), (2, "Embutidos"), (3, "Vacía")],\n        )\n        conexion.executemany(\n            "INSERT INTO proveedores (id_proveedor, nombre, telefono, email) VALUES (?, ?, ?, ?)",\n            [(1, "Prov A", "300", "a@example.com"), (2, "Prov B", None, None)],\n        )\n        conexion.executemany(\n            "INSERT INTO productos (id_producto, nombre, id_categoria, id_proveedor, unidad,"\n            " precio_venta, stock_actual, stock_minimo, activo) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",\n            [\n                (1, "Queso", 1, 1, "KG", 10000, 5, 2, 1),\n                (2, "Leche", 1, 2, "UND", 3000, 1, 4, 1),\n                (3, "Jamón", 2, 1, "KG", 20000, 2, 2, 1),\n                (4, "Viejo", 2, 1, "KG", 5000, 0, 5, 0),\n            ],\n        )\n        conexion.executemany(\n            "INSERT INTO movimientos (id_movimiento, id_producto, id_usuario, tipo, cantidad, fecha)"\n            " VALUES (?, ?, ?, ?, ?, ?)",\n            [\n                (1, 1, 1, "ENTRADA", 10, "2026-10-01 08:00:00"),\n                (2, 1, 1, "SALIDA", 5, "2026-10-02 09:00:00"),\n                (3, 2, 2, "ENTRADA", 12, "2026-10-02 10:00:00"),\n                (4, 3, 2, "SALIDA", 3, "2026-11-01 11:00:00"),\n            ],\n        )\n\n\n@pytest.fixture\ndef cliente(tmp_path, monkeypatch):\n    monkeypatch.delenv("CARGAR_DATOS_EJEMPLO", raising=False)\n    monkeypatch.delenv("ADMIN_PASSWORD", raising=False)\n    monkeypatch.delenv("VENDEDOR_PASSWORD", raising=False)\n    ruta = tmp_path / "reportes.db"\n    preparar_base(ruta)\n    with TestClient(crear_app(ruta)) as cliente:\n        yield cliente\n\n\ndef por_proveedor_o_usuario(filas):\n    return [\n        (f.get("proveedor") or f.get("usuario"), f["unidad"], f["movimientos"], f["entradas"], f["salidas"])\n        for f in filas\n    ]\n\n\ndef test_inventario_por_categoria(cliente):\n    respuesta = cliente.get("/reportes/inventario-por-categoria")\n\n    assert respuesta.status_code == 200\n    filas = [\n        (f["categoria"], f["productos"], f["bajo_minimo"], f["valor_inventario"])\n        for f in respuesta.json()\n    ]\n    # Cuenta solo productos activos; las categorías sin productos aparecen en cero.\n    assert filas == [("Lácteos", 2, 1, 53000), ("Embutidos", 1, 1, 40000), ("Vacía", 0, 0, 0)]\n\n\ndef test_stock_bajo_ordena_por_faltante_y_omite_inactivos(cliente):\n    filas = cliente.get("/reportes/stock-bajo").json()\n\n    assert [f["nombre"] for f in filas] == ["Leche", "Jamón"]\n    assert filas[0]["faltante"] == 3\n    assert filas[0]["proveedor"] == "Prov B"\n    assert filas[0]["proveedor_telefono"] is None\n    assert filas[1]["faltante"] == 0\n    assert filas[1]["proveedor_telefono"] == "300"\n\n\ndef test_movimientos_por_proveedor_con_y_sin_fechas(cliente):\n    todos = cliente.get("/reportes/movimientos-por-proveedor").json()\n    octubre = cliente.get(\n        "/reportes/movimientos-por-proveedor",\n        params={"desde": "2026-10-01", "hasta": "2026-10-31"},\n    ).json()\n    hasta_primero = cliente.get(\n        "/reportes/movimientos-por-proveedor", params={"hasta": "2026-10-01"}\n    ).json()\n    futuro = cliente.get(\n        "/reportes/movimientos-por-proveedor", params={"desde": "2027-01-01"}\n    ).json()\n\n    assert por_proveedor_o_usuario(todos) == [("Prov A", "KG", 3, 10, 8), ("Prov B", "UND", 1, 12, 0)]\n    assert por_proveedor_o_usuario(octubre) == [("Prov A", "KG", 2, 10, 5), ("Prov B", "UND", 1, 12, 0)]\n    assert por_proveedor_o_usuario(hasta_primero) == [("Prov A", "KG", 1, 10, 0)]\n    assert futuro == []\n\n\ndef test_movimientos_por_usuario_separa_por_unidad(cliente):\n    filas = cliente.get("/reportes/movimientos-por-usuario").json()\n\n    assert [(f["usuario"], f["rol"]) for f in filas] == [\n        ("Ana", "ADMINISTRADOR"),\n        ("Beto", "VENDEDOR"),\n        ("Beto", "VENDEDOR"),\n    ]\n    assert por_proveedor_o_usuario(filas) == [\n        ("Ana", "KG", 2, 10, 5),\n        ("Beto", "KG", 1, 0, 3),\n        ("Beto", "UND", 1, 12, 0),\n    ]\n\n\n@pytest.mark.parametrize(\n    "parametros",\n    [\n        {"desde": "2026-12-01", "hasta": "2026-10-01"},\n        {"desde": "hoy"},\n        {"hasta": "2026-13-45"},\n    ],\n)\ndef test_fechas_invalidas_devuelven_422(cliente, parametros):\n    for ruta in ("/reportes/movimientos-por-proveedor", "/reportes/movimientos-por-usuario"):\n        assert cliente.get(ruta, params=parametros).status_code == 422\n\n\ndef test_pagina_de_reportes_esta_disponible(cliente):\n    respuesta = cliente.get("/reportes-ui")\n\n    assert respuesta.status_code == 200\n    assert \'id="reporte"\' in respuesta.text\n    assert "/static/reportes/reportes.js?v=1" in respuesta.text\n\n\n# --- Con autenticación activa ---------------------------------------------------\n\n\n@pytest.fixture\ndef cliente_con_login(tmp_path, monkeypatch):\n    monkeypatch.setenv("AUTH_ACTIVADA", "1")\n    monkeypatch.setenv("SECRET_KEY", "clave-de-prueba")\n    monkeypatch.setenv("CARGAR_DATOS_EJEMPLO", "1")\n    monkeypatch.delenv("ADMIN_PASSWORD", raising=False)\n    monkeypatch.delenv("VENDEDOR_PASSWORD", raising=False)\n    with TestClient(crear_app(tmp_path / "productos.db")) as cliente:\n        yield cliente\n\n\n@pytest.mark.parametrize("ruta", RUTAS_REPORTES)\ndef test_reportes_exigen_sesion(cliente_con_login, ruta):\n    assert cliente_con_login.get(ruta).status_code == 401\n\n\n@pytest.mark.parametrize("ruta", RUTAS_REPORTES)\ndef test_el_vendedor_puede_consultar_reportes(cliente_con_login, ruta):\n    login = cliente_con_login.post(\n        "/auth/login",\n        json={"email": "ventas@salsamentaria.com", "password": "ventas123"},\n    )\n    cabeceras = {"Authorization": f"Bearer {login.json()[\'access_token\']}"}\n\n    respuesta = cliente_con_login.get(ruta, headers=cabeceras)\n\n    assert respuesta.status_code == 200\n    assert isinstance(respuesta.json(), list)\n'}

ESTRICTOS = [('app/main.py', 'from app.api.roles import router as roles_router\n', 'from app.api.reportes import router as reportes_router\nfrom app.api.roles import router as roles_router\n'), ('app/main.py', '    app.add_api_route(\n        "/login-ui",\n', '    app.add_api_route(\n        "/reportes-ui",\n        pagina_reportes,\n        methods=["GET"],\n        response_class=Response,\n        include_in_schema=False,\n    )\n    app.add_api_route(\n        "/login-ui",\n'), ('app/main.py', '    app.include_router(roles_router, dependencies=protegido)\n', '    app.include_router(roles_router, dependencies=protegido)\n    app.include_router(reportes_router, dependencies=protegido)\n'), ('app/main.py', 'def pagina_login():\n', 'def pagina_reportes():\n    return pagina_catalogo("reportes")\n\n\ndef pagina_login():\n'), ('app/static/layout.js', '    { nombre: "Usuarios", ruta: "/usuarios-ui" },\n', '    { nombre: "Reportes", ruta: "/reportes-ui" },\n    { nombre: "Usuarios", ruta: "/usuarios-ui" },\n')]

BLANDOS = [('app/main.py', '            {\n                "name": "Autenticación",\n', '            {\n                "name": "Reportes",\n                "description": "Consultas consolidadas de inventario y movimientos.",\n            },\n            {\n                "name": "Autenticación",\n'), ('README.md', '## Cargar productos\n', '## Reportes\n\nLa opción **Reportes** del menú (`/reportes-ui`) consulta cuatro reportes consolidados. Los pueden ver ambos roles; la API de reportes es solo de lectura.\n\n| Reporte | Ruta | Filtros |\n| --- | --- | --- |\n| Inventario por categoría (productos, bajo el mínimo y valor) | `GET /reportes/inventario-por-categoria` | — |\n| Productos con stock bajo y su proveedor | `GET /reportes/stock-bajo` | — |\n| Movimientos por proveedor (entradas y salidas) | `GET /reportes/movimientos-por-proveedor` | `desde`, `hasta` (opcionales, `AAAA-MM-DD`) |\n| Movimientos por usuario | `GET /reportes/movimientos-por-usuario` | `desde`, `hasta` (opcionales, `AAAA-MM-DD`) |\n\nLas cantidades se separan por unidad (KG o UND) para no sumar kilos con unidades. Cada reporte se puede descargar en CSV desde la página (separado por punto y coma, listo para Excel). Una fecha inicial posterior a la final responde `422`.\n\n## Cargar productos\n'), ('README.md', '| POST | `/auth/usuarios` | Crear un usuario con contraseña (solo administrador) |\n', '| POST | `/auth/usuarios` | Crear un usuario con contraseña (solo administrador) |\n| GET | `/reportes/inventario-por-categoria` | Inventario y valor por categoría |\n| GET | `/reportes/stock-bajo` | Productos en o bajo el stock mínimo |\n| GET | `/reportes/movimientos-por-proveedor` | Entradas y salidas por proveedor |\n| GET | `/reportes/movimientos-por-usuario` | Movimientos registrados por usuario |\n')]

if not Path("app/main.py").exists():
    raise SystemExit("Ejecuta este script desde la raíz del proyecto.")
if not Path("app/seguridad.py").exists():
    raise SystemExit("Falta la autenticación (app/seguridad.py). Haz git pull de main primero.")
for archivo in NUEVOS:
    if Path(archivo).exists():
        raise SystemExit(f"Parece que los reportes ya están aplicados (existe {archivo}).")

textos = {}
for archivo, viejo, _ in ESTRICTOS:
    ruta = Path(archivo)
    if not ruta.exists():
        raise SystemExit(f"No encuentro el archivo {archivo}.")
    textos.setdefault(archivo, ruta.read_text(encoding="utf-8"))
for archivo, viejo, _ in ESTRICTOS:
    if textos[archivo].count(viejo) != 1:
        raise SystemExit(
            f"No encontré (o aparece más de una vez) este texto en {archivo}:\n{viejo}\n"
            "Nada fue modificado. Pásame ese archivo para ajustar el script."
        )

for archivo, viejo, nuevo in ESTRICTOS:
    textos[archivo] = textos[archivo].replace(viejo, nuevo, 1)
for archivo, texto in textos.items():
    Path(archivo).write_text(texto, encoding="utf-8")

for archivo, contenido in NUEVOS.items():
    ruta = Path(archivo)
    ruta.parent.mkdir(parents=True, exist_ok=True)
    ruta.write_text(contenido, encoding="utf-8")

omitidos = []
for archivo, viejo, nuevo in BLANDOS:
    ruta = Path(archivo)
    if ruta.exists() and ruta.read_text(encoding="utf-8").count(viejo) == 1:
        ruta.write_text(ruta.read_text(encoding="utf-8").replace(viejo, nuevo, 1), encoding="utf-8")
    else:
        omitidos.append(archivo)

print("Listo. Archivos nuevos:", len(NUEVOS), "| archivos modificados:", len(textos))
if omitidos:
    print("Aviso: no pude actualizar (cambios opcionales) en:", ", ".join(sorted(set(omitidos))))
